def predict(board, action):
    mouse_row, mouse_col = action[1], action[2]
    mouse_char = board[mouse_row][mouse_col]

    if mouse_char == 'B':
        # Move 'B' to the right and down
        new_row, new_col = mouse_row, mouse_col + 1
        while new_col < 64 and board[new_row][new_col] == 'B':
            new_col += 1
        if new_col < 64:
            board[new_row][new_col], board[mouse_row][mouse_col] = board[mouse_row][mouse_col], board[new_row][new_col]
        else:
            new_row, new_col = mouse_row + 1, 0
            while new_row < 64 and board[new_row][new_col] == 'B':
                new_row += 1
            if new_row < 64:
                board[new_row][new_col], board[mouse_row][mouse_col] = board[mouse_row][mouse_col], board[new_row][new_col]

    elif mouse_char == 'G':
        # Change 'G' to 'S'
        board[mouse_row][mouse_col] = 'S'

    elif mouse_char == 'N':
        # Change 'N' to 'S'
        board[mouse_row][mouse_col] = 'S'

    elif mouse_char == 'W':
        # Change 'W' to 'p'
        board[mouse_row][mouse_col] = 'p'

    return [list(row) for row in board]
